import { isRecord } from "@/lib/narrow"

type FilterOp =
  | "eq"
  | "neq"
  | "lt"
  | "lte"
  | "gt"
  | "gte"
  | "in"
  | "nin"
  | "contains"
  | "startsWith"
  | "endsWith"
  | "isNull"

/** A `Temporal` value or anything else whose `toString()` is ISO 8601; no Temporal dependency needed. */
type TemporalLike = { toString(): string; readonly epochMilliseconds?: number }

type FilterScalar = string | number | boolean | null | Date | TemporalLike

type FilterLeaf = {
  field: string
  op: FilterOp
  /** A list for `in` and `nin`; `true` (is null) or `false` (is not null) for `isNull`. */
  value: FilterScalar | readonly FilterScalar[]
  /** Marks a date, so serializers format it with their `dates` option. */
  type?: "date"
}

type FilterNode = { and: readonly FilterNode[] } | { or: readonly FilterNode[] } | { not: FilterNode } | FilterLeaf

/** `"iso"` keeps strings and writes `Date` as `toISOString()`; `"iso-date"` keeps the date part only. */
type DateFormat = "iso" | "iso-date" | "epoch-ms" | ((value: Date | TemporalLike | string) => string)

const filterOps: readonly FilterOp[] = [
  "eq",
  "neq",
  "lt",
  "lte",
  "gt",
  "gte",
  "in",
  "nin",
  "contains",
  "startsWith",
  "endsWith",
  "isNull",
]

/** Thrown when a filter can't be written safely in a wire format. */
class FilterSerializeError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "FilterSerializeError"
  }
}

const fieldPattern = /^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*$/

/** Field names are identifiers with dotted paths, never free text: anything else is refused. */
function assertFieldName(field: unknown, allowed?: ReadonlySet<string>): string {
  if (typeof field !== "string" || !fieldPattern.test(field))
    throw new FilterSerializeError(`"${String(field)}" isn't a valid field name.`)
  if (allowed && !allowed.has(field)) throw new FilterSerializeError(`"${field}" isn't a field of this filter schema.`)
  return field
}

function isLeaf(node: FilterNode): node is FilterLeaf {
  return "field" in node
}

const negated: Partial<Record<FilterOp, FilterOp>> = {
  eq: "neq",
  neq: "eq",
  lt: "gte",
  lte: "gt",
  gt: "lte",
  gte: "lt",
  in: "nin",
  nin: "in",
}

/**
 * Pushes `not` down to the leaves (De Morgan), for formats without a `not`: `not(a and b)` becomes `not a or not b`.
 * A text match (`contains`…) stays wrapped in `not`; `isNull` flips its value.
 */
function negate(node: FilterNode): FilterNode {
  if ("and" in node) return { or: node.and.map(negate) }
  if ("or" in node) return { and: node.or.map(negate) }
  if ("not" in node) return node.not
  if (node.op === "isNull") return { ...node, value: node.value !== true }
  const op = negated[node.op]
  return op ? { ...node, op } : { not: node }
}

function isTemporalLike(value: unknown): value is TemporalLike {
  return typeof value === "object" && value !== null && !(value instanceof Date) && !Array.isArray(value)
}

function epochOf(value: Date | TemporalLike | string): number {
  if (value instanceof Date) return value.getTime()
  if (typeof value === "string") return Date.parse(value)
  if (typeof value.epochMilliseconds === "number") return value.epochMilliseconds
  return Date.parse(value.toString())
}

/** Writes a date for the wire. A `Date` is written in UTC; strings and Temporal values keep their own form. */
function formatDate(value: Date | TemporalLike | string, format: DateFormat = "iso"): string {
  if (typeof format === "function") return format(value)
  if (format === "epoch-ms") {
    const ms = epochOf(value)
    if (!Number.isFinite(ms)) throw new FilterSerializeError(`"${String(value)}" isn't a date.`)
    return String(ms)
  }
  if (value instanceof Date && Number.isNaN(value.getTime())) throw new FilterSerializeError("Invalid Date.")
  const iso = value instanceof Date ? value.toISOString() : value.toString()
  return format === "iso-date" ? iso.slice(0, 10) : iso
}

/** A scalar as text for formats that write everything as strings; dates go through `formatDate`. */
function scalarText(value: FilterScalar, dates: DateFormat | undefined, isDate: boolean): string {
  if (value === null) return "null"
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new FilterSerializeError(`${String(value)} can't be sent as a filter value.`)
    return String(value)
  }
  if (typeof value === "boolean") return String(value)
  if (value instanceof Date || isTemporalLike(value) || (isDate && typeof value === "string"))
    return formatDate(value, dates)
  return value
}

function valuesOf(leaf: FilterLeaf): readonly FilterScalar[] {
  return Array.isArray(leaf.value) ? (leaf.value as readonly FilterScalar[]) : [leaf.value as FilterScalar]
}

function readPath(item: unknown, path: string): unknown {
  let current = item
  for (const key of path.split(".")) {
    if (!isRecord(current)) return undefined
    current = current[key]
  }
  return current
}

const dateOnly = /^\d{4}-\d{2}-\d{2}$/

function comparable(left: unknown, right: FilterScalar, isDate: boolean): [unknown, unknown] {
  if (!isDate && !(right instanceof Date) && !isTemporalLike(right)) return [left, right]
  if (typeof right === "string" && dateOnly.test(right)) {
    const day = left instanceof Date ? left.toISOString() : typeof left === "string" ? left : ""
    return [day.slice(0, 10), right]
  }
  const ms = (value: unknown) =>
    value instanceof Date || isTemporalLike(value) || typeof value === "string" ? epochOf(value) : Number.NaN
  return [ms(left), ms(right)]
}

function compare(left: unknown, right: unknown) {
  if (typeof left === "string" && typeof right === "string") return left.localeCompare(right)
  if (typeof left === "number" && typeof right === "number") return left - right
  return Number.NaN
}

function text(value: unknown) {
  return String(value ?? "").toLocaleLowerCase()
}

function matchesLeaf(leaf: FilterLeaf, item: unknown): boolean {
  const actual = readPath(item, leaf.field)
  const isDate = leaf.type === "date"
  switch (leaf.op) {
    case "isNull":
      return (actual === null || actual === undefined) === (leaf.value === true)
    case "in":
    case "nin": {
      const found = valuesOf(leaf).some((value) => Object.is(actual, value) || String(actual) === String(value))
      return leaf.op === "in" ? found : !found
    }
    case "contains":
      return text(actual).includes(text(leaf.value))
    case "startsWith":
      return text(actual).startsWith(text(leaf.value))
    case "endsWith":
      return text(actual).endsWith(text(leaf.value))
    default: {
      const [left, right] = comparable(actual, leaf.value as FilterScalar, isDate)
      if (leaf.op === "eq") return left === right || (left !== undefined && String(left) === String(right))
      if (leaf.op === "neq") return !(left === right || String(left) === String(right))
      const order = compare(left, right)
      if (Number.isNaN(order)) return false
      if (leaf.op === "lt") return order < 0
      if (leaf.op === "lte") return order <= 0
      if (leaf.op === "gt") return order > 0
      return order >= 0
    }
  }
}

/** Evaluates a filter against an object in memory, for `arraySource` and tests. Text matches ignore case. */
function matchesFilter(node: FilterNode | null | undefined, item: unknown): boolean {
  if (!node) return true
  if ("and" in node) return node.and.every((child) => matchesFilter(child, item))
  if ("or" in node) return node.or.some((child) => matchesFilter(child, item))
  if ("not" in node) return !matchesFilter(node.not, item)
  return matchesLeaf(node, item)
}

function fieldsOf(node: FilterNode | null | undefined, into = new Set<string>()): Set<string> {
  if (!node) return into
  if ("and" in node) for (const child of node.and) fieldsOf(child, into)
  else if ("or" in node) for (const child of node.or) fieldsOf(child, into)
  else if ("not" in node) fieldsOf(node.not, into)
  else into.add(node.field)
  return into
}

/** Whether a filter holds an `or` or a `not`, which flat query params can't carry. */
function hasGroups(node: FilterNode | null | undefined): boolean {
  if (!node) return false
  if ("or" in node || "not" in node) return true
  if ("and" in node) return node.and.some(hasGroups)
  return false
}

function assertLeaf(leaf: FilterLeaf) {
  if (!filterOps.includes(leaf.op)) throw new FilterSerializeError(`Unknown operator "${String(leaf.op)}".`)
  const list = Array.isArray(leaf.value)
  if ((leaf.op === "in" || leaf.op === "nin") !== list)
    throw new FilterSerializeError(`"${leaf.op}" on "${leaf.field}" ${list ? "can't take" : "needs"} a list.`)
  if (leaf.op === "isNull" && typeof leaf.value !== "boolean")
    throw new FilterSerializeError(`"isNull" on "${leaf.field}" takes true or false.`)
}

export {
  assertFieldName,
  assertLeaf,
  epochOf,
  fieldsOf,
  FilterSerializeError,
  filterOps,
  formatDate,
  hasGroups,
  isLeaf,
  isTemporalLike,
  matchesFilter,
  negate,
  readPath,
  scalarText,
  valuesOf,
}
export type { DateFormat, FilterLeaf, FilterNode, FilterOp, FilterScalar, TemporalLike }

import {
  assertFieldName,
  fieldsOf,
  FilterSerializeError,
  isTemporalLike,
  type FilterLeaf,
  type FilterNode,
  type FilterOp,
  type TemporalLike,
} from "@/lib/filter-ast"
import { assumeType, isOneOf, isRecord, isStringArray } from "@/lib/narrow"
import type { PageSource } from "@/lib/page-source"

type FilterOption = { value: string; label: string }

type TextMatchOp = Extract<FilterOp, "contains" | "startsWith" | "endsWith" | "eq">

/** `{ param: "q" }` sends the text as its own param; `{ fields, op }` matches it against fields, joined by `or`. */
type SearchMapping = { param: string } | { fields: readonly string[]; op?: TextMatchOp }

type FieldBase = {
  /** The field's name in the UI, for chips, the panel and agents. */
  label: string
  /** The field's name on the wire, when it differs from the key. A dotted path reaches a nested field. */
  field?: string
}

type TextField = FieldBase & { kind: "text"; search?: SearchMapping; placeholder?: string }
type OptionsField = FieldBase & { kind: "options"; options: readonly FilterOption[]; multiple?: boolean }
type BooleanField = FieldBase & { kind: "boolean"; trueLabel?: string; falseLabel?: string }
type NumberOp = Extract<FilterOp, "eq" | "neq" | "lt" | "lte" | "gt" | "gte">
type NumberField = FieldBase & {
  kind: "number"
  /** The comparisons offered. Default `["eq", "gte", "lte", "between"]`. */
  operators?: readonly (NumberOp | "between")[]
  min?: number
  max?: number
  step?: number
}
type DateField = FieldBase & { kind: "date"; op?: Extract<FilterOp, "eq" | "lt" | "lte" | "gt" | "gte"> }
type DateRangeField = FieldBase & {
  kind: "dateRange"
  /**
   * The range's end is inclusive. `"lte"` (default) sends `field lte to`, which keeps the whole day when the backend
   * compares dates; `"next-day"` sends `field lt to + 1 day`, for a backend that stores date-times.
   */
  end?: "lte" | "next-day"
}
type RemoteOptionField<Option = unknown> = FieldBase & {
  kind: "remoteOption"
  /** Where the options come from; its filter gets the typed text as `q`. */
  source: PageSource<Option, { q?: string }>
  getLabel(option: Option): string
  /** The value stored for an option. Default: the source's `getId`. */
  getValue?(option: Option): string
  multiple?: boolean
}

type FilterField =
  | TextField
  | OptionsField
  | BooleanField
  | NumberField
  | DateField
  | DateRangeField
  | RemoteOptionField
type FilterSchema = Readonly<Record<string, FilterField>>

type DateInput = string | Date | TemporalLike
type DateRange = { from?: DateInput; to?: DateInput }
type NumberFilter = { op: NumberOp; value: number } | { op: "between"; min: number; max: number }

type FieldValue<Field> = Field extends { kind: "text" }
  ? string
  : Field extends { kind: "options" | "remoteOption"; multiple: true }
    ? readonly string[]
    : Field extends { kind: "options" | "remoteOption" }
      ? string
      : Field extends { kind: "boolean" }
        ? boolean
        : Field extends { kind: "number" }
          ? NumberFilter
          : Field extends { kind: "date" }
            ? DateInput
            : Field extends { kind: "dateRange" }
              ? DateRange
              : never

/** The values of a schema: every field optional, unset means no filter. `$where` adds an expression with groups. */
type FilterValues<S extends FilterSchema> = { -readonly [Key in keyof S]?: FieldValue<S[Key]> } & {
  $where?: FilterNode
}

const reserved = new Set(["$where"])

const numberOps = ["eq", "neq", "lt", "lte", "gt", "gte"] as const satisfies readonly NumberOp[]

/** A comparison a number field offers besides `between`: `eq`, `neq`, `lt`, `lte`, `gt` or `gte`. */
function isNumberOp(value: unknown): value is NumberOp {
  return isOneOf(numberOps, value)
}

/** A number field's value: `{ op, value }` or `{ op: "between", min, max }`. */
function isNumberFilter(value: unknown): value is NumberFilter {
  if (!isRecord(value)) return false
  if (value.op === "between") return typeof value.min === "number" && typeof value.max === "number"
  return isNumberOp(value.op) && typeof value.value === "number"
}

/** A date field's value: an ISO string, a `Date` or a Temporal-like object. */
function isDateInput(value: unknown): value is DateInput {
  return typeof value === "string" || value instanceof Date || isTemporalLike(value)
}

/** A date range's value: `{ from?, to? }`, each a date input. */
function isDateRange(value: unknown): value is DateRange {
  return (
    isRecord(value) &&
    !(value instanceof Date) &&
    ("from" in value || "to" in value) &&
    (value.from === undefined || isDateInput(value.from)) &&
    (value.to === undefined || isDateInput(value.to))
  )
}

type AddsDays = { add(duration: { days: number }): TemporalLike }

const addsDays = (value: object): value is AddsDays => "add" in value && typeof value.add === "function"

/** A `remoteOption` field typed by its source, so `getLabel` knows the option: `owner: remoteOption({ … })`. */
function remoteOption<Option, const Multiple extends boolean = false>(
  field: Omit<RemoteOptionField<Option>, "kind" | "multiple"> & { multiple?: Multiple },
): RemoteOptionField<Option> & { kind: "remoteOption"; multiple: Multiple } {
  // Workaround: `Multiple` defaults to false when `multiple` is left out, a link TypeScript can't draw from the property.
  return { ...field, kind: "remoteOption", multiple: assumeType<Multiple>(field.multiple ?? false) }
}

/** Declares the filters a source accepts. Keys and wire fields must be identifiers: they are the whitelist. */
function defineFilters<const S extends FilterSchema>(schema: S): S {
  for (const [key, field] of Object.entries(schema)) {
    if (reserved.has(key)) throw new FilterSerializeError(`"${key}" is reserved.`)
    assertFieldName(key)
    assertFieldName(field.field ?? key)
    if (field.kind === "text" && field.search && "fields" in field.search)
      for (const name of field.search.fields) assertFieldName(name)
    if (field.kind === "text" && field.search && "param" in field.search) assertFieldName(field.search.param)
  }
  return schema
}

function wireName(key: string, field: FilterField) {
  return field.field ?? key
}

const defaultSearch: SearchMapping = { param: "q" }

function searchOf(field: TextField): SearchMapping {
  return field.search ?? defaultSearch
}

/** Every wire field the schema can produce: the whitelist a `$where` is checked against. */
function schemaFields(schema: FilterSchema): Set<string> {
  const fields = new Set<string>()
  for (const [key, field] of Object.entries(schema)) {
    if (field.kind !== "text") fields.add(wireName(key, field))
    else {
      const search = searchOf(field)
      if ("fields" in search) for (const name of search.fields) fields.add(name)
    }
  }
  return fields
}

/** Whether a value filters anything: unset, empty text, an empty list or an empty range doesn't. */
function isActiveValue(value: unknown): boolean {
  if (value === undefined || value === null) return false
  if (typeof value === "string") return value.trim() !== ""
  if (Array.isArray(value)) return value.length > 0
  if (isRecord(value) && !(value instanceof Date) && ("from" in value || "to" in value))
    return isActiveValue(value.from) || isActiveValue(value.to)
  return true
}

/** The keys of the schema with an active value, in schema order. */
function activeFilterKeys<S extends FilterSchema>(schema: S, values: FilterValues<S>): (keyof S & string)[] {
  return Object.keys(schema).filter((key) => isActiveValue((values as Record<string, unknown>)[key]))
}

function nextDay(value: DateInput): DateInput {
  if (value instanceof Date) return new Date(value.getTime() + 24 * 60 * 60 * 1000)
  if (typeof value === "string") {
    const day = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
    if (!day) throw new FilterSerializeError(`"next-day" needs a date like 2026-01-31, not "${value}".`)
    return new Date(Date.UTC(Number(day[1]), Number(day[2]) - 1, Number(day[3]) + 1)).toISOString().slice(0, 10)
  }
  if (!addsDays(value)) throw new FilterSerializeError(`"next-day" can't add a day to ${String(value)}.`)
  return value.add({ days: 1 })
}

function leaf(field: string, op: FilterOp, value: FilterLeaf["value"], type?: "date"): FilterLeaf {
  return type ? { field, op, value, type } : { field, op, value }
}

function fieldNodes(key: string, field: FilterField, value: unknown): FilterNode[] {
  if (!isActiveValue(value)) return []
  const name = wireName(key, field)
  switch (field.kind) {
    case "text": {
      const search = searchOf(field)
      if ("param" in search) return []
      const text = String(value).trim()
      const nodes = search.fields.map((fieldName) => leaf(fieldName, search.op ?? "contains", text))
      return nodes.length === 1 ? nodes : [{ or: nodes }]
    }
    case "options":
    case "remoteOption":
      if (field.multiple) return isStringArray(value) ? [leaf(name, "in", [...value])] : []
      return [leaf(name, "eq", String(value))]
    case "boolean":
      return [leaf(name, "eq", value === true)]
    case "number": {
      if (!isNumberFilter(value)) return []
      if (value.op === "between") return [leaf(name, "gte", value.min), leaf(name, "lte", value.max)]
      return [leaf(name, value.op, value.value)]
    }
    case "date":
      return isDateInput(value) ? [leaf(name, field.op ?? "eq", value, "date")] : []
    case "dateRange": {
      if (!isRecord(value)) return []
      const { from, to } = value
      const nodes: FilterNode[] = []
      if (isActiveValue(from) && isDateInput(from)) nodes.push(leaf(name, "gte", from, "date"))
      if (isActiveValue(to) && isDateInput(to)) {
        nodes.push(field.end === "next-day" ? leaf(name, "lt", nextDay(to), "date") : leaf(name, "lte", to, "date"))
      }
      return nodes
    }
    default:
      return []
  }
}

/**
 * The values as one canonical filter, joined by `and`; `null` when nothing filters. Text fields mapped to a param
 * stay out of it: read them with `searchTerms`. Field names come only from the schema.
 */
function toFilterAst<S extends FilterSchema>(schema: S, values: FilterValues<S>): FilterNode | null {
  const nodes = Object.entries(schema).flatMap(([key, field]) =>
    fieldNodes(key, field, (values as Record<string, unknown>)[key]),
  )
  if (values.$where) {
    const allowed = schemaFields(schema)
    for (const name of fieldsOf(values.$where)) assertFieldName(name, allowed)
    nodes.push(values.$where)
  }
  if (nodes.length === 0) return null
  return nodes.length === 1 ? nodes[0]! : { and: nodes }
}

/** Text fields mapped to their own param (`{ param: "q" }`, the default), as `{ q: "text" }`. */
function searchTerms<S extends FilterSchema>(schema: S, values: FilterValues<S>): Record<string, string> {
  const terms: Record<string, string> = {}
  for (const [key, field] of Object.entries(schema)) {
    if (field.kind !== "text") continue
    const search = searchOf(field)
    const value = (values as Record<string, unknown>)[key]
    if ("param" in search && typeof value === "string" && value.trim() !== "") terms[search.param] = value.trim()
  }
  return terms
}

/** The schema's text fields, in order: the first is what a search box edits. */
function searchFieldOf<S extends FilterSchema>(schema: S): (keyof S & string) | undefined {
  return Object.keys(schema).find((key) => schema[key]?.kind === "text")
}

export {
  activeFilterKeys,
  defineFilters,
  isActiveValue,
  isDateInput,
  isDateRange,
  isNumberFilter,
  isNumberOp,
  remoteOption,
  schemaFields,
  searchFieldOf,
  searchOf,
  searchTerms,
  toFilterAst,
  wireName,
}
export type {
  BooleanField,
  DateField,
  DateInput,
  DateRange,
  DateRangeField,
  FieldValue,
  FilterField,
  FilterOption,
  FilterSchema,
  FilterValues,
  NumberField,
  NumberFilter,
  NumberOp,
  OptionsField,
  RemoteOptionField,
  SearchMapping,
  TextField,
  TextMatchOp,
}

import {
  assertFieldName,
  assertLeaf,
  FilterSerializeError,
  negate,
  scalarText,
  valuesOf,
  type DateFormat,
  type FilterLeaf,
  type FilterNode,
  type FilterOp,
  type FilterScalar,
} from "@/lib/filter-ast"
import type { FilterSchema, FilterValues } from "@/lib/filter-schema"

type SerializeOptions = {
  /** How dates are written. Default ISO 8601: `"iso"`. */
  dates?: DateFormat
  /** Refuses any field not listed, on top of the identifier check. Pass `schemaFields(schema)`. */
  fields?: ReadonlySet<string>
}

/** Checks every field and operator, so a hand-built filter can't smuggle a name in. */
function walkLeaves(node: FilterNode, visit: (leaf: FilterLeaf) => void) {
  if ("and" in node) for (const child of node.and) walkLeaves(child, visit)
  else if ("or" in node) for (const child of node.or) walkLeaves(child, visit)
  else if ("not" in node) walkLeaves(node.not, visit)
  else visit(node)
}

function checked(node: FilterNode, fields: ReadonlySet<string> | undefined) {
  walkLeaves(node, (leaf) => {
    assertFieldName(leaf.field, fields)
    assertLeaf(leaf)
  })
  return node
}

/** Flattens nested `and`s and pushes every `not` down; throws when an `or` is left, which flat params can't hold. */
function andLeaves(node: FilterNode, format: string): FilterLeaf[] {
  if ("and" in node) return node.and.flatMap((child) => andLeaves(child, format))
  if ("not" in node) {
    const pushed = negate(node.not)
    if ("not" in pushed && "field" in pushed.not)
      throw new FilterSerializeError(`${format} can't negate "${pushed.not.op}".`)
    return andLeaves(pushed, format)
  }
  if ("or" in node)
    throw new FilterSerializeError(
      `${format} carries only "and"; use rsql, odata, springFilter, graphqlWhere or jsonAst.`,
    )
  return [node]
}

type QueryParamStyle = "dto" | "suffix" | "bracket"

const dtoSuffix: Record<FilterOp, string> = {
  eq: "",
  neq: "Not",
  lt: "Before",
  lte: "To",
  gt: "After",
  gte: "From",
  in: "",
  nin: "NotIn",
  contains: "Contains",
  startsWith: "StartsWith",
  endsWith: "EndsWith",
  isNull: "IsNull",
}

const snakeOp: Record<FilterOp, string> = {
  eq: "eq",
  neq: "neq",
  lt: "lt",
  lte: "lte",
  gt: "gt",
  gte: "gte",
  in: "in",
  nin: "nin",
  contains: "contains",
  startsWith: "starts_with",
  endsWith: "ends_with",
  isNull: "is_null",
}

function camel(path: string) {
  return path.replaceAll(/\.([A-Za-z0-9_])/g, (_match, letter: string) => letter.toUpperCase())
}

function paramName(field: string, op: FilterOp, style: QueryParamStyle) {
  if (style === "dto") return camel(field) + dtoSuffix[op]
  if (style === "suffix") return op === "eq" ? field : `${field}_${snakeOp[op]}`
  return `${field}[${op}]`
}

type QueryParamsOptions = SerializeOptions & {
  /**
   * `"suffix"` (default): `status=open`, `created_gte=…`. `"dto"`: `createdFrom`, `createdTo`, `statusNotIn`, as a
   * request DTO names them. `"bracket"`: `created[gte]=…`, `status[in]=…`.
   */
  style?: QueryParamStyle
  /** `"repeat"` (default) sends `status=a&status=b`; `"comma"` sends `status=a,b` and refuses a value with a comma. */
  arrays?: "repeat" | "comma"
  /** Names a param yourself; return `undefined` to use the style's name. */
  name?: (field: string, op: FilterOp) => string | undefined
}

/** Flat query params, `and` only: a backend DTO, json-server, Django filters or bracket params. */
function queryParams(ast: FilterNode | null | undefined, options: QueryParamsOptions = {}): URLSearchParams {
  const { style = "suffix", arrays = "repeat", dates } = options
  const params = new URLSearchParams()
  if (!ast) return params
  for (const leaf of andLeaves(checked(ast, options.fields), "queryParams")) {
    const name = options.name?.(leaf.field, leaf.op) ?? paramName(leaf.field, leaf.op, style)
    const texts = valuesOf(leaf).map((value) => scalarText(value, dates, leaf.type === "date"))
    if (arrays === "comma" && texts.length > 1) {
      if (texts.some((text) => text.includes(",")))
        throw new FilterSerializeError(`A value of "${leaf.field}" holds a comma; use arrays: "repeat".`)
      params.append(name, texts.join(","))
    } else for (const text of texts) params.append(name, text)
  }
  return params
}

type JsonScalar = string | number | boolean | null
type JsonFilterLeaf = { field: string; op: FilterOp; value: JsonScalar | JsonScalar[]; type?: "date" }
type JsonFilterNode = { and: JsonFilterNode[] } | { or: JsonFilterNode[] } | { not: JsonFilterNode } | JsonFilterLeaf

function jsonScalar(value: FilterScalar, dates: DateFormat | undefined, isDate: boolean): JsonScalar {
  if (value === null || typeof value === "boolean") return value
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new FilterSerializeError(`${String(value)} can't be sent as JSON.`)
    return value
  }
  const text = scalarText(value, dates, isDate)
  return dates === "epoch-ms" && (isDate || typeof value !== "string") ? Number(text) : text
}

function toJson(node: FilterNode, dates: DateFormat | undefined): JsonFilterNode {
  if ("and" in node) return { and: node.and.map((child) => toJson(child, dates)) }
  if ("or" in node) return { or: node.or.map((child) => toJson(child, dates)) }
  if ("not" in node) return { not: toJson(node.not, dates) }
  const isDate = node.type === "date"
  const value = Array.isArray(node.value)
    ? valuesOf(node).map((item) => jsonScalar(item, dates, isDate))
    : jsonScalar(node.value as FilterScalar, dates, isDate)
  return isDate ? { field: node.field, op: node.op, value, type: "date" } : { field: node.field, op: node.op, value }
}

/** The filter as plain JSON for a POST body: the whole grammar, nothing to escape. Validate it again on the server. */
function jsonAst(ast: FilterNode | null | undefined, options: SerializeOptions = {}): JsonFilterNode | null {
  if (!ast) return null
  return toJson(checked(ast, options.fields), options.dates)
}

/** Only free text, for a backend that takes nothing but `q`: every text field's words, joined by spaces. */
function searchOnly<S extends FilterSchema>(
  schema: S,
  values: FilterValues<S>,
  options: { param?: string } = {},
): Record<string, string> {
  const param = assertFieldName(options.param ?? "q")
  const words: string[] = []
  for (const [key, field] of Object.entries(schema)) {
    if (field.kind !== "text") continue
    const value = (values as Record<string, unknown>)[key]
    if (typeof value === "string" && value.trim() !== "") words.push(value.trim())
  }
  return words.length === 0 ? {} : { [param]: words.join(" ") }
}

